syntax:
struct Name {
    var property: Type
    mutating func change() { property = newValue }
}

example:
struct Point {
    var x: Int
    var y: Int

    mutating func moveRight() {
        x += 1
    }
}

var p1 = Point(x: 0, y: 0)
var p2 = p1        // نسخ كامل
p2.moveRight()
print(p1.x, p2.x)   // 0 1 — p1 لم يتأثر

syntax:
protocol Name {
    var property: Type { get set }
    func method() -> ReturnType
}

struct Impl: Name { /* التزام بالمتطلبات */ }

example:
protocol Describable {
    var name: String { get }
    func describe() -> String
}

struct Product: Describable {
    var name: String
    func describe() -> String { "المنتج: \(name)" }
}

syntax:
subscript(index: Type) -> ReturnType {
    get { /* إرجاع قيمة */ }
    set(newValue) { /* تعيين قيمة */ }
}

example:
struct Grid {
    var values = Array(repeating: 0, count: 9)
    subscript(row: Int, col: Int) -> Int {
        get { values[row * 3 + col] }
        set { values[row * 3 + col] = newValue }
    }
}

var grid = Grid()
grid[0, 1] = 5

let items: [Any] = [1, "نص", true]

for item in items {
    if let number = item as? Int {
        print("رقم: \(number)")
    }
}

syntax:
func fetch() async -> ReturnType { ... }

let result = await fetch()

Task {
    let result = await fetch()
}

example:
func fetchName() async -> String {
    return "براء"
}

Task {
    let name = await fetchName()
    print("مرحبًا \(name)")
}

syntax:
struct Name: Codable { let field: Type }

let value = try JSONDecoder().decode(Name.self, from: data)
let data = try JSONEncoder().encode(value)

